1	<script type="module">
2	import mermaid from 'https://cdn.jsdelivr.net/npm/mermaid@11/dist/mermaid.esm.min.mjs';
3	import elkLayouts from 'https://cdn.jsdelivr.net/npm/@mermaid-js/layout-elk/dist/mermaid-layout-elk.esm.min.mjs';
4	import svgPanZoom from 'https://cdn.jsdelivr.net/npm/svg-pan-zoom@3.6.2/+esm';
5	
6	mermaid.registerLayoutLoaders(elkLayouts);
7	mermaid.initialize({
8	  startOnLoad: false,
9	  theme: document.documentElement.getAttribute('data-theme') === 'dark' ? 'dark' : 'neutral',
10	  securityLevel: 'strict',
11	  suppressErrorRendering: true,
12	});
13	
14	// 高度自适应参数:框高随图形宽高比等比增长
15	//   MAX_HEIGHT 设为正数  -> 封顶到该值(超出部分用缩放/平移查看)
16	//   MAX_HEIGHT 设为 0 或 Infinity -> 不封顶,框高完全随图形增长
17	const MIN_HEIGHT = 80;
18	const MAX_HEIGHT = 0;
19	const HAS_CAP = Number.isFinite(MAX_HEIGHT) && MAX_HEIGHT > 0;
20	
21	async function renderMermaid(el) {
22	  const pre = el.closest('pre');
23	  if (!pre || pre.hasAttribute('data-render-done')) return;
24	  pre.setAttribute('data-render-done', 'true');
25	
26	  const source = el.textContent;
27	  const id = 'mermaid-' + Math.random().toString(36).slice(2);
28	
29	  try {
30	    const {svg, bindFunctions} = await mermaid.render(id, source);
31	
32	    // 外层容器
33	    const block = document.createElement('div');
34	    block.className = 'mermaid-block';
35	    block.style.cssText = 'position:relative; border:1px solid var(--color-secondary); border-radius:4px; overflow:hidden;';
36	
37	    // SVG 容器(高度稍后根据图形宽高比自适应计算)
38	    const svgContainer = document.createElement('div');
39	    svgContainer.style.cssText = 'width:100%; background:var(--color-box-body);';
40	    svgContainer.innerHTML = svg;
41	    block.appendChild(svgContainer);
42	
43	    // 控制按钮
44	    const controls = document.createElement('div');
45	    controls.style.cssText = 'position:absolute; top:8px; right:8px; display:flex; gap:4px; z-index:10;';
46	    controls.innerHTML = `
47	      <button type="button" class="ui mini icon button" data-act="zoom-in" title="放大">+</button>
48	      <button type="button" class="ui mini icon button" data-act="reset" title="重置">⟲</button>
49	      <button type="button" class="ui mini icon button" data-act="zoom-out" title="缩小">−</button>
50	      <button type="button" class="ui mini icon button" data-act="fit" title="适应">⛶</button>
51	    `;
52	    block.appendChild(controls);
53	
54	    pre.replaceWith(block);
55	    bindFunctions?.(svgContainer);
56	
57	    // 需要让 SVG 自适应容器
58	    const svgEl = svgContainer.querySelector('svg');
59	    svgEl.setAttribute('width', '100%');
60	    svgEl.setAttribute('height', '100%');
61	    svgEl.style.maxWidth = 'none';
62	
63	    // 从 viewBox 读取图形真实宽高比,用于按容器宽度等比换算高度
64	    const vb = (svgEl.getAttribute('viewBox') || '').split(/\s+/).map(Number);
65	    const aspect = (vb.length === 4 && vb[2] > 0 && vb[3] > 0) ? vb[2] / vb[3] : null;
66	
67	    // 根据当前容器宽度计算自适应高度
68	    const fitHeight = () => {
69	      const w = svgContainer.clientWidth || block.clientWidth;
70	      if (!w) return;
71	      // 按容器宽度等比换算自然高度;没有有效 viewBox 时退回到封顶值/600
72	      const natural = aspect ? w / aspect : (HAS_CAP ? MAX_HEIGHT : 600);
73	      let h = Math.max(MIN_HEIGHT, natural);
74	      if (HAS_CAP) h = Math.min(h, MAX_HEIGHT);
75	      svgContainer.style.height = h + 'px';
76	    };
77	
78	    fitHeight();
79	
80	    // 初始化 pan-zoom(fit 让图形完整放入自适应后的视口)
81	    const panZoom = svgPanZoom(svgEl, {
82	      zoomEnabled: true,
83	      controlIconsEnabled: false,
84	      fit: true,
85	      center: true,
86	      minZoom: 0.1,
87	      maxZoom: 20,
88	      zoomScaleSensitivity: 0.3,
89	    });
90	
91	    controls.addEventListener('click', (e) => {
92	      const act = e.target.closest('button')?.dataset.act;
93	      if (!act) return;
94	      if (act === 'zoom-in') panZoom.zoomIn();
95	      else if (act === 'zoom-out') panZoom.zoomOut();
96	      else if (act === 'reset') panZoom.resetZoom(), panZoom.center();
97	      else if (act === 'fit') panZoom.fit(), panZoom.center();
98	    });
99	
100	    // 容器宽度变化时重新计算高度并适应(用宽度变化做防抖,避免改高度引发的回环)
101	    let lastWidth = svgContainer.clientWidth;
102	    new ResizeObserver(() => {
103	      const w = svgContainer.clientWidth;
104	      if (w !== lastWidth) {
105	        lastWidth = w;
106	        fitHeight();
107	      }
108	      panZoom.resize();
109	      panZoom.fit();
110	      panZoom.center();
111	    }).observe(svgContainer);
112	  } catch (err) {
113	    console.error('Mermaid render error:', err);
114	    pre.innerHTML = `<code style="color:red;">Mermaid error: ${err.message}</code>`;
115	  }
116	}
117	
118	const observer = new MutationObserver((mutations) => {
119	  for (const m of mutations) {
120	    for (const node of m.addedNodes) {
121	      if (node.nodeType !== 1) continue;
122	      node.querySelectorAll?.('code.language-mermaid').forEach(renderMermaid);
123	    }
124	  }
125	});
126	observer.observe(document.body, {childList: true, subtree: true});
127	document.querySelectorAll('code.language-mermaid').forEach(renderMermaid);
128	</script>

